import openpyxl
path = '3_51661_answer_inconsistent_color_8607_input.xlsx'
wb = openpyxl.load_workbook(path)
ws = wb['SHOP']
# Build color label per cell in used range
def label(c):
    f = c.fill
    if f is None or f.patternType != 'solid':
        return '.'
    col = f.fgColor
    if col.type == 'rgb':
        rgb = col.rgb
        m = {'FFFFC7CE':'P','FFFFFF00':'Y','FFF2F2F2':'g','FFC6EFCE':'G','00FF0000':'R'}
        return m.get(rgb, rgb[-6:])
    elif col.type == 'theme':
        if col.theme == 9 and abs(col.tint-0.5999633777886288)<1e-9:
            return 'b'
        return f'T{col.theme}'
    elif col.type == 'indexed':
        return f'i{col.value}'
    return '?'
# Print grid columns A..AB rows 1..29
for r in range(1,30):
    row = []
    for c in range(1,29):
        cell = ws.cell(row=r, column=c)
        if cell.value is not None:
            row.append(f'{cell.coordinate}:{label(cell)}={cell.value!r}')
    if row:
        print(' | '.join(row))
