def col_label(c):
    f = c.fill
    if f is None or f.patternType != 'solid':
        return ''
    col = f.fgColor
    if col.type == 'rgb':
        return col.rgb
    elif col.type == 'theme':
        return f'theme{col.theme}_{col.tint:.4f}'
    elif col.type == 'indexed':
        return f'idx{col.value}'
